const DEFAULT_OPTIONS: Pick<KeyframeAnimationOptions, 'easing' | 'fill'> = {
  easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
  fill: 'forwards',
};

interface MotionOptions {
  duration?: number;
  checkConnected?: boolean;
  beforeOpen?: () => void;
  afterOpen?: () => void;
  afterClose?: () => void;
}

interface AnimationItem {
  element?: Element;
  keyframes: Keyframe[] | PropertyIndexedKeyframes | null;
  duration?: number;
}

export const cancelElementAnimations = (element?: Element) => {
  element?.getAnimations?.().forEach((animation) => {
    try {
      animation.cancel();
    } catch {
      // ignore animation cancellation errors
    }
  });
};

const waitAnimation = (animation: Animation) =>
  new Promise<void>((resolve) => {
    let settled = false;
    const settle = () => {
      if (!settled) {
        settled = true;
        resolve();
      }
    };

    animation.onfinish = settle;
    animation.oncancel = settle;
    animation.finished?.then(settle).catch(settle);
  });

const waitForLayout = () =>
  new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

export const createOpenCloseMotion = () => {
  let token = 0;
  let animations: Animation[] = [];

  const cancel = () => {
    token += 1;
    animations.forEach((animation) => {
      try {
        animation.cancel();
      } catch {
        // ignore animation cancellation errors
      }
    });
    animations = [];
  };

  const active = (runToken: number, elements: Array<Element | undefined>, checkConnected = true) =>
    token === runToken && (!checkConnected || elements.every((element) => !element || element.isConnected));

  const run = async ({
    items,
    elements = [],
    fallback,
    checkConnected,
  }: {
    items: AnimationItem[];
    elements?: Array<Element | undefined>;
    fallback?: () => void;
    checkConnected?: boolean;
  }) => {
    cancel();
    const runToken = token;
    const runElements = [...elements, ...items.map(({ element }) => element)];

    animations = items
      .map(({ element, keyframes, duration }) => element?.animate?.(keyframes, { ...DEFAULT_OPTIONS, duration }))
      .filter(Boolean) as Animation[];

    if (animations.length === 0) {
      if (active(runToken, runElements, checkConnected)) {
        fallback?.();
        return true;
      }
      return false;
    }

    await Promise.all(animations.map(waitAnimation));
    const completed = active(runToken, runElements, checkConnected);
    if (completed) {
      animations = [];
    }
    return completed;
  };

  const after = (open: boolean, options: MotionOptions, completed: boolean) => {
    if (completed) {
      open ? options.afterOpen?.() : options.afterClose?.();
    }
    return completed;
  };

  return {
    run,
    cancel,
    dispose: cancel,

    fade: async (element: Element | undefined, open: boolean, options: MotionOptions = {}) => {
      open && options.beforeOpen?.();
      return after(
        open,
        options,
        await run({
          items: [
            {
              element,
              keyframes: [{ opacity: open ? '0' : '1' }, { opacity: open ? '1' : '0' }],
              duration: options.duration,
            },
          ],
          checkConnected: options.checkConnected,
        }),
      );
    },

    height: async (element: HTMLElement | undefined, open: boolean, options: MotionOptions = {}) => {
      if (!element) return false;
      open && options.beforeOpen?.();

      // 打开路径：beforeOpen 同步把 _open 置为 true，但 Stencil 的 render 是异步的，
      // 此时若立刻 getBoundingClientRect 拿到的是 hidden / 空内容下的 0，
      // 配合 WAAPI fill:forwards 会把 height:0px 锁死在 effect 层，
      // 导致 host 高度恒为 0、内容漂浮叠到下一块（KsInlineAlert open 切 true 的塌陷场景）。
      // 通过双 rAF 等到 render flush + 样式合成完成后再测量，并在测量期间把上一轮残留的 inline height 清掉。
      if (open) {
        element.style.height = '';
        element.style.opacity = '0';

        const runToken = token;
        await waitForLayout();
        if (!active(runToken, [element], options.checkConnected)) return false;
      }

      const measured = Math.max(element.getBoundingClientRect().height, element.scrollHeight);
      const from = open ? 0 : measured;
      const to = open ? measured : 0;

      if (open && to === 0) {
        element.style.height = '';
        element.style.opacity = '1';
        return after(open, options, true);
      }

      element.style.height = `${from}px`;
      element.style.opacity = open ? '0' : '1';

      const completed = await run({
        items: [
          {
            element,
            keyframes: [
              { height: `${from}px`, opacity: open ? '0' : '1' },
              { height: `${to}px`, opacity: open ? '1' : '0' },
            ],
            duration: options.duration,
          },
        ],
        checkConnected: options.checkConnected,
      });

      if (!completed) return false;
      element.style.height = open ? '' : '0px';
      element.style.opacity = open ? '1' : '0';
      return after(open, options, true);
    },

    translateFade: async (element: Element | undefined, open: boolean, options: MotionOptions = {}) => {
      open && options.beforeOpen?.();
      return after(
        open,
        options,
        await run({
          items: [
            {
              element,
              keyframes: [
                { transform: `translateY(${open ? '-8px' : '0'})`, opacity: open ? '0' : '1' },
                { transform: `translateY(${open ? '0' : '-8px'})`, opacity: open ? '1' : '0' },
              ],
              duration: options.duration,
            },
          ],
          elements: [element],
          checkConnected: options.checkConnected,
        }),
      );
    },
  };
};
